// Package manifest holds the manifest of the generated files and the stale
// rule. It replaces sync-engine/manifest, with the same output, files and
// return codes, for the link modes `repo` and `macos`.
//
// Contract: docs/design/sync-engine.md ("The manifest and the stale rule").
package manifest

import (
	"os"
	"sort"
	"strconv"
	"strings"
	"syscall"

	"github.com/virajp/bootstrap/sync-engine/internal/fail"
	"github.com/virajp/bootstrap/sync-engine/internal/header"
	"github.com/virajp/bootstrap/sync-engine/internal/report"
	"github.com/virajp/bootstrap/sync-engine/internal/target"
)

// FirstLine is the first line of a manifest. A reader skips each `#` line.
const FirstLine = "# Written by bootstrap. Do not edit this file."

// LinkMode is the link mode of a side: Repo or Macos.
type LinkMode string

// The link modes.
const (
	// Repo follows no symlink: a listed path below a link stays, and a
	// manifest below a link is not read.
	Repo LinkMode = "repo"
	// Macos removes the real file behind a link.
	Macos LinkMode = "macos"
)

// Row is one row of a manifest: `<tool><TAB><path>` for a generated file, or
// `<tool><TAB><path><TAB><item>` for an item that bootstrap added to a shared
// file. <item> is the identity of the item as JSON on one line.
type Row struct{ Tool, Path, Item string }

// String gives the row as a line without the newline.
func (r Row) String() string {
	if r.Item != "" {
		return r.Tool + "\t" + r.Path + "\t" + r.Item
	}
	return r.Tool + "\t" + r.Path
}

// Items gives the item rows of <rows> for each path.
func Items(rows []Row) map[string][]string {
	out := map[string][]string{}
	for _, r := range rows {
		if r.Item != "" {
			out[r.Path] = append(out[r.Path], r.Item)
		}
	}
	return out
}

// BadPath is _se_manifest_bad_path: true when <p> is not a clean path below
// the root: empty, absolute, with an empty, `.` or `..` segment, or a `.git`
// segment in any case.
func BadPath(p string) bool {
	s := "/" + p + "/"
	if strings.Contains(s, "//") || strings.Contains(s, "/./") || strings.Contains(s, "/../") {
		return true
	}
	for _, seg := range strings.Split(p, "/") {
		if len(seg) == 4 && seg[0] == '.' && strings.ToLower(seg[1:]) == "git" {
			return true
		}
	}
	return false
}

func isLink(path string) bool {
	info, err := os.Lstat(path)
	return err == nil && info.Mode()&os.ModeSymlink != 0
}

func exists(path string) bool { _, err := os.Stat(path); return err == nil }

// Read is _se_manifest_read: it gives each valid row of the manifest <file>.
// A missing file gives no row. A row without a TAB, with an empty tool or
// with a bad path is skipped, with a log line. In Repo mode, <file> is below
// <root>, and it must be a regular file with no symlink between <root> and
// it: else it gives no row and code 2, after a log line. Another <mode> gives
// code 2, after a usage line.
func Read(e *target.Env, mode LinkMode, file, root string) ([]Row, fail.Code) {
	r := e.Report
	switch mode {
	case Repo:
		root = strings.TrimSuffix(root, "/")
		if Linked(root, strings.TrimPrefix(file, root+"/")) {
			r.Log(e.Show(file) + ": the manifest is a link or is below a linked folder - not read")
			return nil, fail.Usage
		}
		if info, err := os.Stat(file); err == nil && !info.Mode().IsRegular() {
			r.Log(e.Show(file) + ": the manifest is not a regular file - not read")
			return nil, fail.Usage
		}
	case Macos:
	default:
		r.Log("usage: _se_manifest_read repo|macos <file> [<root>]")
		return nil, fail.Usage
	}
	if !exists(file) {
		return nil, fail.OK
	}
	// A file that cannot be read (for example a folder in Macos mode) gives
	// no row, as the read loop of bash.
	data, _ := os.ReadFile(file)
	lines := strings.Split(string(data), "\n")
	if lines[len(lines)-1] == "" {
		lines = lines[:len(lines)-1]
	}
	var rows []Row
	for i, line := range lines {
		if line == "" || line[0] == '#' {
			continue
		}
		tool, path, ok := strings.Cut(line, "\t")
		path, item, _ := strings.Cut(path, "\t")
		if !ok || tool == "" || BadPath(path) {
			r.Log(e.Show(file) + ": line " + strconv.Itoa(i+1) + " is not <tool><TAB><path> - skipped")
			continue
		}
		rows = append(rows, Row{tool, path, item})
	}
	return rows, fail.OK
}

// Linked is _se_manifest_linked: true when the path <rest> below <root> is a
// symlink, or a folder between <root> and it is a symlink. <root> itself is
// not tested.
func Linked(root, rest string) bool {
	folder := root
	for {
		i := strings.IndexByte(rest, '/')
		if i < 0 {
			break
		}
		folder += "/" + rest[:i]
		rest = rest[i+1:]
		if isLink(folder) {
			return true
		}
	}
	return isLink(folder + "/" + rest)
}

// Foreign is _se_manifest_foreign: true when a folder between <root> and the
// file <rest> below it has its own `.git`: the file is in another repository.
func Foreign(root, rest string) bool {
	folder := root
	for {
		i := strings.IndexByte(rest, '/')
		if i < 0 {
			return false
		}
		folder += "/" + rest[:i]
		rest = rest[i+1:]
		if exists(folder + "/.git") {
			return true
		}
	}
}

// Same is _se_manifest_same: true when the file <file> is the same file as a
// path of <handled> below <root>, for example another spelling of that path
// on a file system that ignores case.
func Same(file string, handled []string, root string) bool {
	a, err := os.Stat(file)
	if err != nil {
		return false
	}
	for _, p := range handled {
		if p == "" {
			continue
		}
		if b, err := os.Stat(root + "/" + p); err == nil && os.SameFile(a, b) {
			return true
		}
	}
	return false
}

// Real is _se_manifest_real: the real path of the absolute <path>. Each
// symlink, of the file or of a parent folder, is followed, also when its
// source is missing. It gives false on a symlink loop.
func Real(path string) (string, bool) { return real(path, 0) }

func real(p string, hops int) (string, bool) {
	if hops > 64 {
		return "", false
	}
	for strings.HasSuffix(p, "/") && p != "/" {
		p = p[:len(p)-1]
	}
	if p == "" || p == "/" {
		return "/", true
	}
	dir, base := p, p
	if i := strings.LastIndexByte(p, '/'); i >= 0 {
		dir, base = p[:i], p[i+1:]
	}
	if dir == "" {
		dir = "/"
	}
	dir, ok := real(dir, hops+1)
	if !ok {
		return "", false
	}
	switch base {
	case ".", "":
		return dir, true
	case "..":
		up := dir
		if i := strings.LastIndexByte(dir, '/'); i >= 0 {
			up = dir[:i]
		}
		if up == "" {
			up = "/"
		}
		return up, true
	}
	if dir == "/" {
		p = "/" + base
	} else {
		p = dir + "/" + base
	}
	if isLink(p) {
		link, err := os.Readlink(p)
		if err != nil {
			return "", false
		}
		if !strings.HasPrefix(link, "/") {
			link = dir + "/" + link
		}
		return real(link, hops+1)
	}
	return p, true
}

// Prune is _se_manifest_prune: it removes each empty parent folder of the
// file <path> below <root>, from the file up. It stops at <root>, at a
// symlinked folder or at a folder that is not empty.
func Prune(root, path string) {
	dir := root + "/" + path
	cut := func(s string) string {
		if i := strings.LastIndexByte(s, '/'); i >= 0 {
			return s[:i]
		}
		return s
	}
	dir = cut(dir)
	for strings.HasPrefix(dir, root+"/") {
		if isLink(dir) || syscall.Rmdir(dir) != nil {
			return
		}
		dir = cut(dir)
	}
}

// Stale is _se_manifest_stale, the stale rule. Each row of <rows> whose path
// is not in <handled> (each path that this run handled) is a candidate. A
// file that is not there, that has no header, or that is the same file as a
// handled path stays with no log line. Else the file is removed (with a dry
// run, listed), then its empty parent folders. In Repo mode, a path below a
// link or in another repository stays. It gives 1 after a failed removal; the
// other rows still run. Another <mode> gives 2, after a usage line.
func Stale(e *target.Env, mode LinkMode, rows []Row, handled []string, root string) fail.Code {
	r := e.Report
	root = strings.TrimSuffix(root, "/")
	if mode != Repo && mode != Macos {
		r.Log("usage: _se_manifest_stale repo|macos <old-rows> <handled> <root> <dry-run>")
		return fail.Usage
	}
	inHandled := map[string]bool{}
	for _, p := range handled {
		inHandled[p] = true
	}
	rc := fail.OK
	for _, row := range rows {
		path := row.Path
		// An item row is not a file: the merge of its shared file uses it.
		if inHandled[path] || row.Item != "" {
			continue
		}
		file := root + "/" + path
		if mode == Repo {
			if Linked(root, path) {
				if r.Verbose() {
					r.Log("kept " + path + " (link)")
				}
				continue
			}
			if Foreign(root, path) {
				if r.Verbose() {
					r.Log("kept " + path + " (another repository)")
				}
				continue
			}
		} else {
			real, ok := Real(file)
			if !ok {
				continue
			}
			file = real
		}
		if !header.HasFile(file) || Same(file, handled, root) {
			continue
		}
		show := e.Show(root + "/" + path)
		if e.DryRun {
			e.Plan(file)
			r.Outcome(report.Removed, show, "", "would remove "+show)
			continue
		}
		if err := os.Remove(file); err != nil && !os.IsNotExist(err) {
			r.Outcome(report.Failed, show, "cannot remove", "cannot remove "+show)
			rc = fail.Other
			continue
		}
		r.Outcome(report.Removed, show, "", "removed    "+show)
		Prune(root, path)
	}
	return rc
}

// Write is _se_manifest_write: it writes <file> with the first line, then
// <rows> sorted (bytes, each row once), with LF line endings and one LF at
// the end. A <file> with the same content stays as it is, with no line. A
// write reports `changed` or `new`; a dry run only reports it. It gives 1,
// after a log line, when it cannot write.
func Write(e *target.Env, file string, rows []Row) fail.Code {
	r := e.Report
	show := e.Show(file)
	kind := report.Changed
	if !exists(file) {
		kind = report.New
	}
	set := map[string]bool{}
	var lines []string
	for _, row := range rows {
		s := row.String()
		for _, l := range strings.Split(s, "\n") {
			if l != "" && !set[l] {
				set[l] = true
				lines = append(lines, l)
			}
		}
	}
	sort.Strings(lines)
	content := FirstLine + "\n"
	if len(lines) > 0 {
		content += strings.Join(lines, "\n") + "\n"
	}
	if info, err := os.Stat(file); err == nil && info.Mode().IsRegular() {
		if cur, err := os.ReadFile(file); err == nil && string(cur) == content {
			return fail.OK
		}
	}
	if e.DryRun {
		e.Plan(file)
		r.Outcome(kind, show, "", "would write "+show)
		return fail.OK
	}
	cannot := func() fail.Code {
		r.Log("cannot write " + show)
		return fail.Other
	}
	if err := os.MkdirAll(target.Dirname(file), 0o777); err != nil {
		return cannot()
	}
	tmp, err := e.Temps.Create(target.Dirname(file))
	if err != nil {
		return cannot()
	}
	if os.WriteFile(tmp, []byte(content), 0o600) != nil || os.Chmod(tmp, 0o644) != nil || target.Move(tmp, file) != nil {
		os.Remove(tmp)
		return cannot()
	}
	r.Outcome(kind, show, "", "wrote      "+show)
	return fail.OK
}
